def min_extra_chars(s, dictionary):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(len(dictionary))]

    for i in range(n):
        for j in range(len(dictionary)):
            if i + j < n:
                dp[j][i + j] = min(dp[j][i + j], dp[j][i] + dp[j][i + 1])

