def lexicographically_smallest(s):
    # Create a dictionary to store the result
    result = {}

    # Iterate over the string
    for i in range(len(s)):
        # If the current character is not in the result, add it
        if s[i] not in result:
            result[s[i]] = s[i]
        # If the current character is in the result, replace it with the previous character
        else:
            result[s[i]] = result[s[i]][0]

    # Return the smallest string
    return min(result, key=result.get)

