def longestSubarray(nums, k):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            if nums[j] == nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp[i] for i in range(n + 1) if dp[i] <= k)

def findZeroRequests(n, logs, x, queries):
    arr = [0] * queries.length
    for i in range(queries.length):
        start = queries[i] - x
        end = queries[i]
        for server_id, time in logs:
            if time >= start and time <= end:
                arr[i] += 1
                break
    return arr

def moveMarbles(nums, moveFrom, moveTo):
