def minPartition(nums):
    n = len(nums)
    if n == 0:
        return 0

    max_nums1 = max(nums)
    min_nums2 = min(nums)

    for i in range(n):
        if nums[i] > max_nums1:
            max_nums1 = nums[i]
        if nums[i] < min_nums2:
            min_nums2 = nums[i]

    return abs(max_nums1 - min_nums2)

