    string_counts = {
        "AA": 0,
        "BB": 0,
        "AB": 0
    }

    # Add the strings to the dictionary
    for i in range(x):
        string_counts["AA"] += 1
    for i in range(y):
        string_counts["BB"] += 1
    for i in range(z):
        string_counts["AB"] += 1

    # Check if the string "AAA" or "BBB" is a substring
    for i in range(x):
        if string_counts["AA"] == 1:
            if string_counts["BB"] == 1:
                return 0
            else:
                return 1
    for i in range(y):
        if string_counts["BB"] == 1:
            if string_counts["AA"] == 1:
                return 0
            else:
                return 1
    for i in range(z):
        if string_counts["AB"] == 1:
            if string_counts["AA"] == 1:
                return 0
            else:
                return 1

    # If none of the substrings are found, return the maximum length
    return max(string_counts.values())

