def longestSubarray(nums, threshold):
    l = 0
    r = 0
    max_length = 0

    while l < len(nums) and r < len(nums):
        if nums[l] % 2 == 0:
            if nums[l] <= threshold:
                max_length = max(max_length, r - l + 1)
                l += 1
        elif nums[l] % 2 != nums[l + 1] % 2:
            max_length = max(max_length, r - l + 1)
            l += 1
        else:
            r += 1
    return max_length

