            min_string += b[i]
        elif count_dict[a[i]] > 0 and count_dict[b[i]] == 0 and count_dict[c[i]] > 0:
            min_string += c[i]
        elif count_dict[a[i]] > 0 and count_dict[b[i]] > 0 and count_dict[c[i]] == 0:
