def can_make_all_zero(nums, k):
    # Check if the array is empty
    if not nums:
        return True

    # Initialize the result
    result = False

    # Iterate over the array
    for i in range(len(nums)):
        # If the current subarray is not k elements long, continue
        if len(nums[i:i+k]) != k:
            continue

        # Decrease all elements in the subarray by 1
        for j in range(k):
            nums[i+j] -= 1

        # Check if all elements are now 0
        if nums[i+k-1] == 0:
            result = True
            break

    return result

def min_letter_changes(s, k):
    # Create a dictionary to store the number of changes for each substring
    changes = {}

    # Initialize the dictionary with the initial string
    for i in range(len(s)):
        changes[s[i:i+k]] = 0

    # Iterate over the string
    for i in range(len(s)):
        # Check if the substring is a palindrome
        if s[i:i+k] == s[i:i+k][::-1]:
            # Update the number of changes for the substring
            changes[s[i:i+k]] += 1

    # Return the minimum number of changes
    return min(changes.values())

def split_words(words, separator):
