def count_ways_to_express_n(n, x):
    # Calculate the number of unique integers up to n
    unique_numbers = [i for i in range(1, n + 1) if i not in set(range(1, n + 1))]

    # Calculate the number of ways to express n as the sum of the x^th power of unique integers
    ways = 1
    for i in unique_numbers:
        ways *= (i ** x)

    return (ways % 10**9 + 7)

def longestValidSubstring(word, forbidden):
    # Create a dictionary to store the valid substrings
    valid_substrings = {}

    # Iterate through the word and add valid substrings to the dictionary
    for i in range(len(word)):
        forbidden_substrings = [word[i:j] for j in range(i+1, len(word)) if word[i:j] not in forbidden]
        forbidden_substrings.sort()
        valid_substrings[word[i:j]] = forbidden_substrings

    # Find the longest valid substring
    max_length = 0
    max_substring = ""
    for substring in valid_substrings:
        if len(substring) > max_length:
            max_length = len(substring)
            max_substring = substring

    return max_length

