    for i in range(len(word) - k + 1):
        # Check if the substring is complete
        if all(abs(ord(c1) - ord(c2)) <= 2 for c1, c2 in zip(word[i:i+k], word[i+k:i+2*k])):
            count[word[i:i+k]] = count.get(word[i:i+k], 0) + 1

    # Return the count of complete substrings
    return sum(count.values())

