def minCost(source, target, original, changed, cost):
    n = len(source)
    dp = [[-1] * n for _ in range(n)]
    dp[0][0] = 0
    for i in range(1, n):
        for j in range(1, n):
            if original[i] == changed[j] and cost[i] == cost[j]:
                dp[i][j] = dp[i-1][j-1] + 1
            elif original[i] == changed[j] and cost[i] < cost[j]:
                dp[i][j] = dp[i-1][j] + 1
            elif original[i] != changed[j] and cost[i] == cost[j]:
                dp[i][j] = min(dp[i][j], dp[i-1][j]) + 1
            elif original[i] != changed[j] and cost[i] < cost[j]:
                dp[i][j] = min(dp[i][j], dp[i-1][j]) + 1
    return dp[n-1][n-1]

