def markAllIndices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)

    # Initialize all indices as unmarked
    for i in range(n):
        nums[i] = 0

    # Mark all indices in nums
    for s in range(1, m):
        # Choose an index i in the range [1, n]
        i = changeIndices[s]
        # Decrement nums[i] by 1
        nums[i] -= 1
        # If nums[changeIndices[s]] is equal to 0, mark the index
        if nums[changeIndices[s]] == 0:
            changeIndices[s] = i

    # Return the earliest second when all indices can be marked
    for s in range(1, m):
        if nums[changeIndices[s]] == 0:
            return s

    return -1

