def find_guarded_vertices(N, M, K):
    graph = {}
    for i in range(N):
        graph[i] = {}
        for j in range(i+1, N+1):
            graph[i][j] = 0

    for i in range(M):
        a, b = map(int, input().split())
        graph[a][b] = 1
        graph[b][a] = 1

    p = {}
    for i in range(K):
        p[i] = int(input())

    h = {}
    for i in range(K):
        h[i] = int(input())

    def dfs(v):
        if v in p:
            return p[v]
        if v in h:
            return h[v]
        if v not in graph:
            return -1
        d = 0
        for w in graph[v]:
            if w not in p and w not in h:
                d += dfs(w)
        return d + 1

    guarded = []
    for v in range(N):
        if dfs(v) == h[v]:
            guarded.append(v)

    return len(guarded), guarded

