def find_directed_cycle(n, edges):
    # Create a dictionary to store the visited vertices
    visited = {i: False for i in range(n + 1)}

    # Initialize the cycle
    cycle = []

    # Iterate through the edges
    for i in range(n):
        # If the current edge is not visited, add it to the cycle
        if not visited[edges[i]]:
            cycle.append(edges[i])
            visited[edges[i]] = True

    # If the cycle is not empty, it is a directed cycle
    if cycle:
        return len(cycle)
    else:
        return 0
