    for i in range(1, N+1):
        for j in range(1, D_i+1):
            if all(int(d) == int(i) and int(d) == int(j) for d in str(i) + str(j)):
                count += 1
    return count

def count_repeats(s, l, r):
    count = 0
    for i in range(l, r+1):
        if s[i] == s[i+1]:
            count += 1
    return count

def count_repeats_query(N, Q, S, l, r):
    counts = [0] * (N+1)
    for i in range(N):
        counts[S[i]] += 1
    for i in range(Q):
        l, r = l, r
        while l < r:
            if counts[S[l]] == 2:
                counts[S[l]] -= 1
                l += 1
            if counts[S[r]] == 2:
                counts[S[r]] -= 1
                r -= 1
    return [counts[i] for i in range(N+1)]

