def delete_vertex(N, edges):
    # Initialize the number of operations to 0
    operations = 0

    # Initialize a dictionary to store the number of operations for each vertex
    vertex_operations = {vertex: 0 for vertex in range(N + 1)}

    # Iterate over the edges
    for u, v in edges:
        # If the vertex is not a leaf, add 1 to the operations for the vertex
        if u != v:
            vertex_operations[u] += 1
            vertex_operations[v] += 1
        # If the vertex is a leaf, add 1 to the operations for the vertex
        else:
            vertex_operations[u] += 1
            vertex_operations[v] += 1

    # Find the minimum number of operations required to delete vertex 1
    for vertex in range(N + 1):
        if vertex_operations[vertex] == 1:
            operations += 1

    return operations

