def max_sleighs(N, queries):
    sleighs = [0] * N
    reindeer = [0] * N

    for i in range(N):
        reindeer[i] = queries[i]

    for i in range(N):
        for j in range(i + 1, N):
            if reindeer[i] + reindeer[j] <= queries[i] + queries[j]:
                sleighs[i] = max(sleighs[i], sleighs[j] + 1)
                sleighs[j] = max(sleighs[j], sleighs[i] + 1)

    return sleighs

