        if v in visited:
            return
        visited.add(v)
        path.append(v)
        for u in graph[v]:
            if u not in visited:
                dfs(u, visited, path)
        path.pop()
        visited.remove(v)

    graph = {}
    for i in range(N):
        for j in range(i+1, N):
            graph[i] = graph.get(j, []) + [j]
            graph[j] = graph.get(i, []) + [i]

    visited = set()
    path = []
    dfs(1, visited, path)
    if len(path) == N:
        return sum(graph[v] for v in path)
    else:
        return -1

