def is_possible(A, B, C, X):
    # Check if the sum of A, B, and C is equal to X
    if sum(A) + sum(B) + sum(C) != X:
        return False

    # Check if the sum of A, B, and C is less than X
    if sum(A) + sum(B) + sum(C) < X:
        return False

    # Check if the sum of A, B, and C is greater than X
    if sum(A) + sum(B) + sum(C) > X:
        return False

    # Check if the sum of A, B, and C is equal to X
    if sum(A) + sum(B) + sum(C) == X:
        return True

    return False

