    colors = set()
    count = 0

    for i in range(1, M + 1):
        if T[i - 1] == 1:
            for j in range(A[i - 1], W + 1):
                if X[i - 1] == X[j - 1]:
                    count += 1
                    colors.add(X[j - 1])
        elif T[i - 1] == 2:
            for j in range(A[i - 1], W + 1):
                if X[i - 1] == X[j - 1]:
                    count += 1
                    colors.add(X[j - 1])

