    distances = [float('inf')] * N
    for i in range(N):
        for j in range(i + 1, N):
            if points[i][0] != points[j][0]:
                continue
            if points[i][1] != points[j][1]:
                continue
            distances[i] = min(distances[i], distances[j] + math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2))
    return distances

