    min_operations = min(operations.values())

    # Return the minimum number of operations required to make word k-periodic
    return min_operations

def minAnagramLength(s):
    # Create a dictionary to store the count of each character in the string
    char_count = {}

    # Iterate over the string
    for char in s:
        # If the character is not in the dictionary, add it and increment its count
        if char not in char_count:
            char_count[char] = 1
        else:
            char_count[char] += 1

    # Initialize the minimum length of t to the length of the string s
    min_length = len(s)

    # Iterate over the characters in the string s
    for char in s:
        # If the character is in the dictionary, increment its count
        if char in char_count:
            char_count[char] += 1

        # If the count of the character is greater than 1, it means it is an anagram of t
        if char_count[char] > 1:
            # Update the minimum length of t
            min_length = min(min_length, len(char) + 1)

    return min_length

def can_create_square(grid):
    # Check if the grid is already a 2x2 square
    if len(grid) == 2 and len(grid[0]) == 2:
        return True

    # Check if the grid is already a 2x2 square of the same color
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == grid[i][j+1] and grid[i][j] == grid[i][j+2] and grid[i][j] == grid[i+1][j] and grid[i][j] == grid[i+2][j]:
                return True

    return False

def right_triangles(grid):
    # Create a dictionary to store the number of right triangles
    right_triangles = {}

    # Iterate over the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # Check if the current element is 1
            if grid[i][j] == 1:
                # Check if the current element is in the same row and column with another element
                if i != j and grid[i][j] == grid[i][j - 1] and grid[i][j] == grid[i][j + 1]:
                    # Increment the count of right triangles
                    right_triangles[grid[i][j]] = right_triangles.get(grid[i][j], 0) + 1

    # Return the count of right triangles
    return right_triangles.values()

def stable_binary_arrays(zero, one, limit):
    # Initialize the count of stable binary arrays
    count = 0

    # Iterate over all possible binary arrays
    for i in range(2**limit):
        # Check if the binary array is stable
        if (i & (i - 1)) == 0 and (i & (i - 2)) == 1:
            count += 1

    return count % (10**9 + 7)

def permutation_difference(s, t):
    if len(s) != len(t):
        return "Error: The lengths of s and t must be equal."

    # Create a dictionary to store the indices of each character in s
    indices = {char: i for i, char in enumerate(s)}

    # Create a dictionary to store the indices of each character in t
    t_indices = {char: i for i, char in enumerate(t)}

    # Calculate the permutation difference
    diff = 0
    for char in s:
        diff += abs(indices[char] - t_indices[char])

    return diff

def maxEnergy(energy, k):
    max_energy = 0
    for i in range(len(energy)):
        if energy[i] > 0:
            max_energy += energy[i]
        elif energy[i] < 0:
            max_energy += energy[i] + k
    return max_energy

def isSpecialArray(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 != nums[i + 1] % 2:
            return True
    return False

def digit_difference(nums):
    # Create a dictionary to store the digit differences
    digit_diffs = {}

    # Iterate over all pairs of integers
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            # Get the digits of the two integers
            digit1 = int(nums[i])
            digit2 = int(nums[j])

            # Calculate the digit difference
            digit_diff = abs(digit1 - digit2)

            # Update the dictionary with the digit difference
            digit_diffs[digit_diff] = digit_diffs.get(digit_diff, 0) + 1

    # Return the sum of the digit differences
    return sum(digit_diffs.values())

def staircase_jump(k):
    if k == 0:
        return 2
    elif k == 1:
        return 4
    else:
        return (2 * staircase_jump(k - 1) + 2**(k - 1)) // 2

def good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % nums2[j] * k == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        if word[i] == 'a' or word[i] == 'b' or word[i] == 'c' or word[i] == 'd' or word[i] == 'e':
            comp += str(i) + word[i]
        else:
            comp += str(len(word[i:])) + word[i]
    return comp

def partition(s):
    # Create a dictionary to store the count of each character
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Create a list to store the balanced substrings
    balanced_substrings = []

    # Iterate through the characters in the string
    for char in s:
        # If the character is not in the dictionary, it means it is an unbalanced character
        if char not in char_count:
            # Add the character to the balanced substrings list
            balanced_substrings.append(char)
        # If the character is in the dictionary, it means it is a balanced character
        else:
            # Remove the character from the balanced substrings list
            balanced_substrings.pop()

    # Return the minimum number of substrings
    return len(balanced_substrings)

def powerful_array(x):
    powers = [1, 2, 8]
    for i in range(1, x + 1):
        powers.append(powers[-1] * 2)
    return powers

def big_nums(x):
    powers = powerful_array(x)
    return [powers[i] for i in range(len(powers))]

def query(queries):
    big_nums = big_nums(10**9)
    answer = []
    for i in range(len(queries)):
        from_i, to_i, mod_i = queries[i]
        product = 1
        for j in range(from_i, to_i + 1):
            product *= big_nums[j]
        answer.append(product % mod_i)
    return answer

def find_xor(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
    xor = 0
    for num in count:
        if count[num] > 1:
            xor ^= num
    return xor

def findOccurrences(nums, queries, x):
    answer = []
    for i in range(len(queries)):
        if queries[i] in nums:
            answer.append(nums.index(queries[i]))
        else:
            answer.append(-1)
    return answer
